public void processOperation(ISMBatchableTelemetryContract _contract)
{
    /*
    int64 batchElapsedHours;
    int maxBatchHours = SABatchTracingParameters::findOrCreate().MaxBatchHours;
    int taskCreatePerBundle = SABatchTracingParameters::findOrCreate().TaskCreatePerBundle;
    Args args = new Args();
    */

    /*
    if (SABatchTracingHelper::isAnotherTracingBatchRunning(currentTask))
    {
        info("@SABatchTracing:ExistingInstance");
    }
    else
    */
    {
        ISMBatchableTelemetryParameterSetup telemetryParameterSetup;
        telemetryParameterSetup = ISMBatchableTelemetryParameterSetup::findByTaskServiceClass(
            _contract.parmBatchableTelemetryTaskServiceClass());

        ISMBatchableTelemetryStatusTable::initAndUpdateRecords(telemetryParameterSetup);
        ISMBatchableTelemetryStatusTable::cleanupStatusRecords(telemetryParameterSetup);

        this.floodServers(_contract, telemetryParameterSetup);

        utcdatetime startBatchTime = DateTimeUtil::utcNow();
        int pollingDelayStartStop = 10; // SABatchTracingParameters::findOrCreate().PollingDelayStartStop;
        boolean startRequested = false;
        boolean stopRequested = true;
        Batch currentTask = BatchHeader::getCurrentBatchTask();
        do
        {
            // Continously monitor the server states and update if necessary.
            // This includes adding or removing servers in case the environment is scaled up or down.
            // This will also set a server status to NotReady if the batch task for that server
            // is no longer executing (e.g. in case of an error).
            ISMBatchableTelemetryStatusTable::initAndUpdateRecords(telemetryParameterSetup);

            // Stops batch jobs that were incorrectly created with just telemetry collection tasks.
            // See comment in floodServers method for details.
            /* TODO
            ISMBatchableTelemetryStatusTable::stopBatchTasksInWrongBatchJobs(
                telemetryParameterSetup, currentTask.BatchJobId);
            */

            // Check if the servers need to be flooded again, in case a server was added or a
            // batch task has failed.
            if (ISMBatchableTelemetryStatusTable::needsFlooding(telemetryParameterSetup))
            {
                this.floodServers(_contract, telemetryParameterSetup);

                startRequested = false;
            }

            // Keep Controller Task Active while batch is running.
            // TODO: Controller class is checked to prevent duplicate batch jobs from starting.
            // Previous comment from batch tracing, unclear how it relates to the next line or how this is done.
            ISMBatchableTelemetryStatusTable::updateStatusOfAllServersRecord(telemetryParameterSetup);

            Batch batch;
            ISMBatchableTelemetryStatusTable statusTable;
            select firstonly1 batch
                exists join statusTable
                    where batch.RecId == statusTable.Batch
                        && statusTable.ParameterSetup == telemetryParameterSetup.RecId;
            ISMBatchableTelemetryHelper::cleanupFinishedBatchTasks(batch.BatchJobId);

            // Check for all servers start / stop
            ISMBatchableTelemetryStatusTable allServersStatusTable = 
                ISMBatchableTelemetryStatusTable::findByTelemetryAndServer(
                    telemetryParameterSetup, ISMBatchableTelemetryConstants::AllServers);
            if (allServersStatusTable.Status == ISMBatchableTelemetryStatus::StartRequested 
                && !startRequested)
            {
                ISMBatchableTelemetryStatusTable::startTelemetryCollectionOnAllServers(telemetryParameterSetup);
                startRequested = true;
                stopRequested = false;
            }
            else if (allServersStatusTable.Status == ISMBatchableTelemetryStatus::StopRequested 
                && !stopRequested)
            {
                // TODO ISMBatchableTelemetryHelper::stopTelemetryCollectionOnAllServers(telemetryParameterSetup);
                startRequested = false;
                stopRequested = true;
            }

            sleep(pollingDelayStartStop * 1000);

        }
        while (!ISMBatchableTelemetryHelper::isTelemetryBatchJobCancelled(currentTask.BatchJobId));

        ISMBatchableTelemetryStatusTable::updateStatus(
            telemetryParameterSetup, 
            ISMBatchableTelemetryConstants::AllServers, 
            ISMBatchableTelemetryStatus::NotReady);
    }
}

/// <summary>
/// Floods all servers with telemetry tasks.
/// New batch tasks will be created until all servers have a task executing or the maximum number 
/// of tasks has been created.
/// </summary>
/// <param name = "_contract">The telemetry contract.</param>
/// <param name = "_telemetryParameterSetup">The telemetry parameter setup.</param>
public void floodServers(
    ISMBatchableTelemetryContract _contract,
    ISMBatchableTelemetryParameterSetup _telemetryParameterSetup)
{
    BatchHeader batchHeader;
    Batch batch;
    ISMBatchableTelemetryStatusTable statusTable;
    select firstonly1 batch 
        exists join statusTable
            where batch.RecId == statusTable.Batch
                && statusTable.ParameterSetup == _telemetryParameterSetup.RecId;
    if (batch.RecId != 0)
    {
        batchHeader = BatchHeader::construct(batch.BatchJobId);
    }
    else
    {
        batchHeader = BatchHeader::construct();
    }
    int taskCountMax;
    int maxTaskToCreate = ISMBatchableTelemetryConstants::MaxTaskToCreate;
    int pollingDelayTaskBundle = 30; // SABatchTracingParameters::findOrCreate().PollingDelayTaskBundle;
    do
    {
        int taskCount = 1;
        int taskCreatePerBundle = 100; // SABatchTracingParameters::findOrCreate().TaskCreatePerBundle;
        while (taskCount <= taskCreatePerBundle)
        {
            ISMBatchableTelemetryTaskController batchableTelemetryTaskController =
                    new ISMBatchableTelemetryTaskController(
                    _contract.parmBatchableTelemetryTaskServiceClass(),
                    _contract.parmBatchableTelemetryTaskServiceMethod());
            Object contract = batchableTelemetryTaskController.getDataContractObject();
            ISMBatchableTelemetryContract batchableTelemetryContract;
            if (contract && contract is ISMBatchableTelemetryContract)
            {
                batchableTelemetryContract = contract as ISMBatchableTelemetryContract;
                batchableTelemetryContract.parmBatchableTelemetryTaskServiceClass(
                        _telemetryParameterSetup.BatchableTelemetryTaskServiceClass);
                batchableTelemetryContract.parmBatchableTelemetryTaskServiceMethod(
                        'processOperation');
            }
            batchableTelemetryTaskController.parmDialogCaption("Batchable Telemetry Task");
            batchHeader.addTask(batchableTelemetryTaskController);
            batchHeader.save();
            taskCount++;
            taskCountMax++;
        }

        if (!ISMBatchableTelemetryStatusTable::existsTaskOnAllServers(_telemetryParameterSetup))
        {
            sleep(pollingDelayTaskBundle * 1000); // Sleep polling bundle and try to launch more
        }
    }
    while (!ISMBatchableTelemetryStatusTable::existsTaskOnAllServers(_telemetryParameterSetup)
            && taskCountMax < maxTaskToCreate);
}
